    const arrayToString = (array)=>{
        return array.join(';\n');
    };
    const processProperty = (key, value)=>{
        // Your logic to process each property
        // console.log(`const ${key} =  ${JSON.stringify(value)};\n`);
        let _value = `const ${key} =  ${JSON.stringify(value, null, 2).replace(/"([^"]+)":/g, '$1:')}`;
        return _value;
    };
    const createJsonObject = (array)=>{
        const jsonObject = {};
        array.forEach((item1)=>{
            const { code, companyCd, description, length, name, subCodes, useYn } = item1;
            jsonObject[code] = {
                companyCd,
                code,
                name,
                length,
                description,
                useYn,
                subCodes
            };
        });
        return jsonObject;
    };
    const removeDuplicates = (array, key)=>{
        const seen = new Set();
        return array.filter((item1)=>{
            const keyValue = item1[key];
            if (seen.has(keyValue)) return false;
            else {
                seen.add(keyValue);
                return true;
            }
        });
    };
    const groupByCode = (array)=>{
        console.log("groupByCode", array);
        const map = new Map();
        let _idx = 1;
        array.forEach((item1)=>{
            const code = item1.code;
            if (!map.has(code)) {
                map.set(code, []);
                _idx = 1;
            }
            const modifiedItem = removeProperty(item1, 'subCodes');
            const _subcode = {
                mst_cd: modifiedItem.code,
                subCd: modifiedItem.subCode,
                name: modifiedItem.subName,
                order: _idx++,
                description: modifiedItem.description,
                useYn: modifiedItem.useYn
            };
            map.get(code).push(_subcode);
        });
        return Array.from(map.values());
    };
